{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Private practice therapy</title>
  <meta name="description" content="Practical, confidential therapy in {{CITY}}, {{STATE}}. Short series and flexible options to help you find steadier footing.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <meta name="theme-color" content="#F7F6F3">
</head>
<body>
  <header class="site-header">
    <div class="container">
      <a class="brand" href="index.html">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary Navigation">
        <a href="index.html">Welcome</a>
        <a href="about.html">Who I Am</a>
        <a href="specialties.html">Who I Support</a>
        <a href="approach.html">Ways I Work</a>
        <a href="fees.html">Investment</a>
        <a href="faq.html">Questions</a>
        <a href="book.html" class="cta">Book a time</a>
        <a href="contact.html" class="muted">Visit</a>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero">
      <svg class="pattern" aria-hidden="true">
        <use href="assets/img/pattern.svg#pattern" />
      </svg>
      <div class="container hero-grid">
        <div class="hero-copy">
          <h1 class="title">Gentle clarity for practical next steps</h1>
          <p class="lede">I offer short series and single-session formats for adults seeking clear-minded, confidential support. Sessions are practical, clinically informed, and tailored to what you need right now.</p>
          <p class="meta">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>

          <div class="hero-actions">
            <a href="{{PRIMARY_CTA_URL}}" class="primary-cta">{{PRIMARY_CTA_LABEL}}</a>
            <a href="contact.html" class="secondary">Ask a question</a>
          </div>
        </div>

        <aside class="hero-panel" aria-labelledby="panel-heading">
          <h2 id="panel-heading">Quick entry points</h2>
          <ul class="entry-list">
            <li><strong>Short series</strong> — 4–6 focused sessions to map the immediate concern.</li>
            <li><strong>Single-session consult</strong> — one reflective hour to plan next steps.</li>
            <li><strong>Clinical membership</strong> — ongoing check-ins when you want steady support.</li>
          </ul>

          <div class="mood-widget">
            <label for="mood" class="label">Where are you today?</label>
            <div id="mood" class="mood-options" role="radiogroup" aria-label="Mood to method selector">
              <button data-key="overwhelmed" aria-checked="false">Overwhelmed</button>
              <button data-key="stuck" aria-checked="false">Stuck</button>
              <button data-key="transitioning" aria-checked="false">Transitioning</button>
              <button data-key="coping" aria-checked="false">Coping</button>
            </div>
            <div id="mood-result" class="mood-result" aria-live="polite">
              <p class="method-title">Recommended approach</p>
              <p class="method-copy">Select how you feel to see a suggested path and a tailored call-to-action.</p>
              <a id="mood-cta" class="mood-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            </div>
          </div>
        </aside>
      </div>
    </section>

    <!-- GALLERY (visual metaphors) -->
    <section class="gallery container" aria-labelledby="gallery-heading">
      <h2 id="gallery-heading">Ways we might work together</h2>
      <div class="cards">
        <article class="card">
          <div class="card-visual" aria-hidden="true">
            <svg viewBox="0 0 100 100"><rect x="0" y="0" width="100" height="100" fill="#FEF7E6"/></svg>
          </div>
          <h3>Focused Series</h3>
          <p>4–6 sessions centered on a specific concern — practical tools, an agreed plan, homework optional.</p>
        </article>

        <article class="card">
          <div class="card-visual" aria-hidden="true">
            <svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="50" fill="#E9F6F2"/></svg>
          </div>
          <h3>Single Session</h3>
          <p>A single hour to clarify priorities, rehearse difficult conversations, or get an action plan.</p>
        </article>

        <article class="card">
          <div class="card-visual" aria-hidden="true">
            <svg viewBox="0 0 100 100"><path d="M0 100 L100 0 L100 100 Z" fill="#F3E8FF"/></svg>
          </div>
          <h3>Ongoing Check-Ins</h3>
          <p>Flexible monthly or biweekly sessions for steady reflection and course correction.</p>
        </article>
      </div>
    </section>

    <!-- WHAT TO EXPECT (includes Pricing Comparator) -->
    <section class="what-to-expect container" aria-labelledby="expect-heading">
      <h2 id="expect-heading">What to expect</h2>
      <div class="expect-grid">
        <div>
          <h3>Confidential, direct, and practical</h3>
          <p>Sessions are confidential within professional and legal limits. We clarify concerns, set reasonable objectives, and track progress. I avoid quick fixes; we focus on sustainable movement toward your goals.</p>

          <h4>Boundaries & scope</h4>
          <p>I do not provide emergency services. If you are in crisis or at immediate risk, contact local emergency services or a crisis line. Therapy involves emotional work; we discuss limits, timelines, and coordination with other care if needed.</p>
        </div>

        <aside>
          <h3>Compare booking styles</h3>
          <p class="muted">Toggle between per-session billing and bundled package pricing. Numbers animate to give a sense of monthly cost vs. up-front package.</p>

          <div class="pricing-comparator" aria-hidden="false">
            <div class="toggle">
              <label class="switch">
                <input id="price-toggle" type="checkbox">
                <span class="slider"></span>
              </label>
              <span class="label-left">Per session</span>
              <span class="label-right">Package</span>
            </div>

            <div class="price-display">
              <div>
                <div class="price-label">Short series</div>
                <div class="price-amount" data-monthly="140" data-package="760">$140</div>
                <div class="price-sub">per session / or package rate</div>
              </div>

              <div>
                <div class="price-label">Single session</div>
                <div class="price-amount" data-monthly="165" data-package="155">$165</div>
                <div class="price-sub">one hour</div>
              </div>

              <div>
                <div class="price-label">Membership (monthly)</div>
                <div class="price-amount" data-monthly="95" data-package="540">$95</div>
                <div class="price-sub">billed monthly or prepay package</div>
              </div>
            </div>

            <p class="disclaimer">Fees may vary by format (telehealth vs in-person) and are discussed before booking. Insurance reimbursement is your responsibility; I can provide a receipt.</p>
          </div>
        </aside>
      </div>
    </section>

    <!-- OBJECTIONS / QUESTIONS -->
    <section class="objections container" aria-labelledby="objections-heading">
      <h2 id="objections-heading">Common questions</h2>
      <details>
        <summary>How long will it take?</summary>
        <p>Length depends on the issue and goals. Some people find a short series enough; others appreciate ongoing check-ins. We'll set expectations together and review progress periodically.</p>
      </details>

      <details>
        <summary>What if I'm unsure about therapy?</summary>
        <p>Starting with a single session or a brief series is common. We can treat early sessions as investigative: decide whether the approach fits your needs without long commitments.</p>
      </details>

      <details>
        <summary>Do you accept insurance?</summary>
        <p>I do not bill insurance directly here. I provide documentation you can submit for potential reimbursement. We'll discuss practical options before scheduling.</p>
      </details>
    </section>

    <!-- CTA -->
    <section class="final-cta">
      <div class="container">
        <h2>Ready to take a practical step?</h2>
        <p>If you'd like to talk, choose a booking option that feels manageable. I keep scheduling simple and private.</p>
        <div class="cta-row">
          <a id="primary-cta-bottom" class="primary-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a href="faq.html" class="secondary">Read common questions</a>
        </div>
        <p class="small">Confidentiality note: communications are confidential within professional and legal boundaries. For urgent safety concerns, contact local emergency services immediately.</p>
      </div>
    </section>
  </main>

  <footer class="site-footer" role="contentinfo">
    <div class="container footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p class="muted">Serving {{CITY}}, {{STATE}} • Private practice therapy</p>
      </div>
      <div>
        <p><a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p class="small">Licensed clinician. This site is not an emergency resource. If you are in immediate danger, call local emergency services.</p>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
