{"path":"assets/css/styles.css","content":"/* Basic reset and utilities */
:root{
  --bg:#FFFDFB; --muted:#6B6B6B; --accent:#5D7C8A; --accent-2:#7A6A9B; --card:#FFFFFF; --shadow:0 6px 18px rgba(20,20,30,0.06);
  --radius:10px; --max:1100px; --gap:20px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; background:var(--bg); color:#222; line-height:1.45}
.container{max-width:var(--max);margin:0 auto;padding:28px}
.site-header{background:linear-gradient(180deg,#FFF 60%,#F6F4F2);border-bottom:1px solid #EEE}
.site-header .container{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--accent);text-decoration:none}
.main-nav a{margin-left:16px;color:#444;text-decoration:none;font-size:15px}
.main-nav a.cta{background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px}
.main-nav a.muted{color:var(--muted)}

/* Hero */
.hero{position:relative;padding:48px 0 36px;overflow:hidden}
.hero .pattern{position:absolute;right:-10%;top:-10%;width:420px;height:420px;opacity:0.65}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:start}
.title{font-size:28px;margin:0 0 10px}
.lede{color:var(--muted);margin:0 0 14px}
.meta{font-size:13px;color:var(--muted);margin-bottom:18px}
.hero-actions .primary-cta{background:var(--accent);color:#fff;padding:12px 16px;border-radius:8px;text-decoration:none;margin-right:8px}
.hero-actions .secondary{color:var(--accent);text-decoration:none}
.hero-panel{background:linear-gradient(180deg,#fff,#FBFBFB);padding:18px;border-radius:12px;box-shadow:var(--shadow)}
.hero-panel h2{margin-top:0}
.entry-list{padding-left:18px;color:var(--muted)}

.mood-widget{margin-top:16px}
.mood-options{display:flex;gap:8px;margin-top:8px}
.mood-options button{background:#FFF;border:1px solid #E7E7E7;padding:8px 10px;border-radius:8px;cursor:pointer}
.mood-options button[aria-checked="true"]{background:var(--accent);color:#fff;border-color:transparent}
.mood-result{margin-top:12px;background:#fff;padding:12px;border-radius:8px;border:1px solid #F0F0F0}
.mood-result .method-title{font-weight:600;margin:0}
.mood-cta{display:inline-block;margin-top:8px;padding:8px 12px;background:var(--accent-2);color:#fff;border-radius:8px;text-decoration:none}

/* Gallery */
.gallery{padding:18px 28px}
.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:12px}
.card{background:var(--card);padding:14px;border-radius:12px;box-shadow:var(--shadow)}
.card-visual{height:80px;border-radius:8px;overflow:hidden;margin-bottom:10px}
.card h3{margin:6px 0}

/* What to expect */
.what-to-expect{padding:28px}
.expect-grid{display:grid;grid-template-columns:1fr 360px;gap:24px}
.pricing-comparator{background:#fff;padding:14px;border-radius:12px;border:1px solid #EEE}
.toggle{display:flex;align-items:center;gap:8px;margin-bottom:12px}
.switch{position:relative;display:inline-block;width:46px;height:26px}
.switch input{opacity:0;width:0;height:0}
.slider{position:absolute;cursor:pointer;top:0;left:0;right:0;bottom:0;background:#ccc;border-radius:26px}
.slider:before{position:absolute;content:"";height:18px;width:18px;left:4px;top:4px;background:white;border-radius:50%;transition:transform .25s}
.switch input:checked + .slider{background:var(--accent-2)}
.switch input:checked + .slider:before{transform:translateX(20px)}
.price-display{display:grid;grid-template-columns:1fr;gap:10px}
.price-display > div{background:#FBFBFB;padding:10px;border-radius:8px}
.price-label{font-weight:600}
.price-amount{font-size:20px;margin-top:6px}
.price-sub{color:var(--muted);font-size:13px}
.disclaimer{font-size:12px;color:var(--muted);margin-top:8px}

/* Objections */
.objections details{background:#fff;padding:12px;border-radius:8px;border:1px solid #EEE;margin-bottom:10px}
.objections summary{cursor:pointer;font-weight:600}

/* Final CTA */
.final-cta{background:linear-gradient(180deg,#FFF,#FAFCFF);padding:28px 0;border-top:1px solid #EEE}
.cta-row{display:flex;gap:12px;margin-top:12px}
.primary-cta{background:var(--accent);color:#fff;padding:12px 16px;border-radius:8px;text-decoration:none}
.secondary{background:transparent;color:var(--accent);padding:10px;text-decoration:none}
.small{font-size:13px;color:var(--muted)}

/* Footer */
.site-footer{border-top:1px solid #EEE;padding:18px 0;margin-top:20px}
.footer-grid{display:flex;justify-content:space-between;align-items:center}
.muted{color:var(--muted)}

@media (max-width:900px){
  .hero-grid, .expect-grid{grid-template-columns:1fr}
  .cards{grid-template-columns:1fr}
  .main-nav{display:none}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mood-to-Method selector
  var moodButtons = document.querySelectorAll('#mood .mood-options button');
  var moodResultTitle = document.querySelector('#mood-result .method-title');
  var moodResultCopy = document.querySelector('#mood-result .method-copy');
  var moodCta = document.getElementById('mood-cta');
  var bottomCta = document.getElementById('primary-cta-bottom');

  var moods = {
    overwhelmed: {
      title: 'Stabilizing plan',
      copy: 'Short, practical steps focused on immediate coping and reducing reactivity. We set a few small, achievable goals and check progress session-to-session.',
      cta: 'Schedule a stabilizing session'
    },
    stuck: {
      title: 'Exploratory focus',
      copy: 'A series that maps patterns, tests small changes, and builds momentum. We prioritize clarity and practical experiments between sessions.',
      cta: 'Book an exploratory series'
    },
    transitioning: {
      title: 'Transition guidance',
      copy: 'Support that helps you navigate choices and new roles with realistic planning and emotional steadiness.',
      cta: 'Plan transitional support'
    },
    coping: {
      title: 'Maintenance check-ins',
      copy: 'Short periodic check-ins to maintain gains and troubleshoot new challenges as they arise.',
      cta: 'Start regular check-ins'
    }
  };

  function selectMood(key, button){
    // update ARIA and styles
    moodButtons.forEach(function(b){
      b.setAttribute('aria-checked','false');
      b.classList.remove('active');
    });
    if(button){ button.setAttribute('aria-checked','true'); button.classList.add('active'); }

    var data = moods[key];
    if(!data) return;
    // morph content
    moodResultTitle.textContent = data.title;
    moodResultCopy.textContent = data.copy;
    moodCta.textContent = data.cta;
    // create a contextual link (append a query for tracking, not external)
    var base = '{{PRIMARY_CTA_URL}}';
    moodCta.href = base + '?focus=' + encodeURIComponent(key);
    // also update bottom CTA to be more specific but keep base
    if(bottomCta){ bottomCta.textContent = data.cta; bottomCta.href = base + '?focus=' + encodeURIComponent(key); }
  }

  moodButtons.forEach(function(b){
    b.addEventListener('click', function(){
      var key = b.getAttribute('data-key');
      selectMood(key,b);
    });
    b.addEventListener('keydown', function(e){ if(e.key==='Enter' || e.key===' '){ e.preventDefault(); b.click(); } });
  });

  // Pricing comparator animation
  var toggle = document.getElementById('price-toggle');
  var amounts = document.querySelectorAll('.price-amount');
  var animating = false;

  function animateNumber(el, from, to, duration){
    if(animating) return; animating = true;
    var start = null;
    var diff = to - from;
    function step(ts){
      if(!start) start = ts;
      var progress = Math.min((ts - start)/duration, 1);
      var current = Math.round(from + diff * easeOutCubic(progress));
      el.textContent = '$' + current;
      if(progress < 1) requestAnimationFrame(step); else animating = false;
    }
    requestAnimationFrame(step);
  }
  function easeOutCubic(t){ return (--t)*t*t + 1 }

  function updatePrices(usePackage){
    amounts.forEach(function(el){
      var monthly = parseInt(el.getAttribute('data-monthly'),10);
      var pack = parseInt(el.getAttribute('data-package'),10);
      var from = parseInt(el.textContent.replace(/[^0-9]/g,''),10) || monthly;
      var to = usePackage ? pack : monthly;
      animateNumber(el, from, to, 550);
    });
  }

  if(toggle){
    toggle.addEventListener('change', function(){ updatePrices(toggle.checked); });
    // initialize from DOM data attributes
    // ensure visible values match monthly by default
    amounts.forEach(function(el){ el.textContent = '$' + el.getAttribute('data-monthly'); });
  }

  // Accessibility: keyboard focus styles for mood options
  document.addEventListener('keydown', function(e){
    if(e.key === 'Tab') document.body.classList.add('user-tab');
  });

  // Expose a small debug hook
  window.__therapyDemo = { selectMood: selectMood, updatePrices: updatePrices };
})();
"} 
